const storeClosures = `-- name: StoreClosures :many
SELECT store_id, closed_at, closed_by, closed_by_measure_id, reopened_at, open_closed_at
FROM seller.store_closures
WHERE store_id = $1
ORDER BY closed_at
`

// 一個 stint 的關店歷史（含目前這一次），舊到新。
func (q *Queries) StoreClosures(ctx context.Context, storeID int64) ([]SellerStoreClosure, error) {
	rows, err := q.db.Query(ctx, storeClosures, storeID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SellerStoreClosure{}
	for rows.Next() {
		var i SellerStoreClosure
		if err := rows.Scan(
			&i.StoreID,
			&i.ClosedAt,
			&i.ClosedBy,
			&i.ClosedByMeasureID,
			&i.ReopenedAt,
			&i.OpenClosedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

